class Solution(object):
    def countAlternatingSubarrays(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        p = 1
        cur_len = 1
        ans = 0
        while p < n:
            if nums[p] != nums[p - 1]:
                cur_len += 1
            else:
                ans += (cur_len + 1) * cur_len / 2
                cur_len = 1
            p += 1
        if cur_len > 0:
            ans += (cur_len + 1) * cur_len / 2
        return ans
